import{_ as a,o as d,c as s,a4 as e}from"./chunks/framework.BBs01uty.js";const S=JSON.parse('{"title":"前端渲染方式","description":"","frontmatter":{"title":"前端渲染方式","date":"2023-03-01T00:00:00.000Z"},"headers":[],"relativePath":"engineering/rendering.md","filePath":"engineering/rendering.md"}'),n={name:"engineering/rendering.md"};function i(r,t,l,p,h,o){return d(),s("div",null,[...t[0]||(t[0]=[e(`<h2 id="渲染方式概览" tabindex="-1">渲染方式概览 <a class="header-anchor" href="#渲染方式概览" aria-label="Permalink to &quot;渲染方式概览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缩写</th><th>全称</th><th>核心思想</th><th>代表框架</th></tr></thead><tbody><tr><td>CSR</td><td>Client Side Rendering</td><td>浏览器下载 JS 后自行渲染页面</td><td>React/Vue SPA</td></tr><tr><td>SSR</td><td>Server Side Rendering</td><td>服务器返回完整 HTML，客户端激活交互</td><td>Next.js、Nuxt.js</td></tr><tr><td>SSG</td><td>Static Site Generation</td><td>构建时预渲染静态 HTML，部署到 CDN</td><td>Hugo、Hexo、VitePress</td></tr><tr><td>ISR</td><td>Incremental Site Rendering</td><td>SSG 升级版，按需逐页增量构建</td><td>Next.js (getStaticProps + revalidate)</td></tr><tr><td>DPR</td><td>Distributed Persistent Rendering</td><td>ISR 改进版，去除 fallback，按需构建器响应</td><td>Netlify</td></tr></tbody></table><h2 id="csr-客户端渲染" tabindex="-1">CSR 客户端渲染 <a class="header-anchor" href="#csr-客户端渲染" aria-label="Permalink to &quot;CSR 客户端渲染&quot;">​</a></h2><p>服务器返回空 HTML + JS/CSS，浏览器下载并执行脚本后自行构建页面。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器请求 → 服务器返回空HTML+JS/CSS → 浏览器执行JS → 请求API数据 → 渲染页面</span></span></code></pre></div><p><strong>特点</strong>：</p><ul><li>切换页面通过前端路由控制，无需重新请求服务器</li><li>SPA 的典型实现方式</li><li>首屏白屏时间长，SEO 不友好</li></ul><h2 id="ssr-服务端渲染" tabindex="-1">SSR 服务端渲染 <a class="header-anchor" href="#ssr-服务端渲染" aria-label="Permalink to &quot;SSR 服务端渲染&quot;">​</a></h2><p>服务器接收请求后执行 JS，将组件渲染成 HTML 字符串返回给浏览器。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器请求 → 服务器执行JS渲染HTML → 返回完整HTML → 浏览器展示 → 客户端JS激活交互(hydration)</span></span></code></pre></div><p><strong>优势</strong>：</p><ul><li>首屏速度快：用户直接看到完整页面，无需等待 JS 下载执行</li><li>SEO 友好：搜索引擎爬虫可以直接抓取完整 HTML</li></ul><p><strong>代价</strong>：</p><table tabindex="0"><thead><tr><th>代价</th><th>说明</th></tr></thead><tbody><tr><td>服务器成本</td><td>需要额外服务器，需视流量扩容</td></tr><tr><td>部署地域受限</td><td>距离服务器较远的用户响应慢（CSR 可从就近 CDN 取资源）</td></tr><tr><td>运维负担</td><td>需要监控告警、日志、容灾等，增加人力成本</td></tr><tr><td>TTI 未提升</td><td>客户端仍需下载 JS 并执行 hydration 后才能交互</td></tr></tbody></table><h2 id="ssg-静态站点生成" tabindex="-1">SSG 静态站点生成 <a class="header-anchor" href="#ssg-静态站点生成" aria-label="Permalink to &quot;SSG 静态站点生成&quot;">​</a></h2><p>在构建阶段预渲染所有页面，生成静态 HTML 部署到 CDN。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>构建时渲染HTML → 部署到CDN → 用户请求直接从CDN获取</span></span></code></pre></div><p><strong>适用场景</strong>：内容更新不频繁的网站（博客、文档站、官网）</p><p><strong>局限</strong>：每次内容变更都需要重新构建全量页面，页面数量多时构建时间很长</p><h2 id="isr-增量式静态生成" tabindex="-1">ISR 增量式静态生成 <a class="header-anchor" href="#isr-增量式静态生成" aria-label="Permalink to &quot;ISR 增量式静态生成&quot;">​</a></h2><p>SSG 的升级版，解决海量页面构建慢的问题。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户访问页面 → 返回缓存的HTML</span></span>
<span class="line"><span>  → 页面未过期：直接返回缓存</span></span>
<span class="line"><span>  → 页面已过期：返回缓存 + 异步重新构建 → 更新CDN缓存</span></span></code></pre></div><p><strong>核心机制</strong>：</p><ul><li>页面有过期时间（revalidate）</li><li>过期时仍先返回缓存内容（不阻塞用户）</li><li>后台异步重新构建，完成后更新 CDN</li></ul><p><strong>适用场景</strong>：页面数量大、内容有一定更新频率但不要求实时的站点（电商商品页、新闻站）</p><h2 id="dpr-分布式持续渲染" tabindex="-1">DPR 分布式持续渲染 <a class="header-anchor" href="#dpr-分布式持续渲染" aria-label="Permalink to &quot;DPR 分布式持续渲染&quot;">​</a></h2><p>在 ISR 基础上改进，由 Netlify 提出：</p><table tabindex="0"><thead><tr><th>改进点</th><th>ISR</th><th>DPR</th></tr></thead><tbody><tr><td>未缓存页面</td><td>回退到 SSG 构建</td><td>用 On-demand Builder 实时渲染并缓存</td></tr><tr><td>页面过期</td><td>返回过期缓存 + 异步更新</td><td>回源到 Builder 渲染最新内容</td></tr><tr><td>版本发布</td><td>需手动清缓存</td><td>自动清除 CDN 缓存</td></tr></tbody></table><p><strong>问题</strong>：</p><ol><li>新页面首次访问可能触发同步渲染，响应较慢</li><li>难以防御 DoS 攻击（大量访问新页面导致 Builder 并行运行）</li></ol><h2 id="渲染方式演进" tabindex="-1">渲染方式演进 <a class="header-anchor" href="#渲染方式演进" aria-label="Permalink to &quot;渲染方式演进&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CSR --&gt;|首屏优化| SSR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SSR --&gt;|减轻服务器压力| SSG</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SSG --&gt;|海量页面构建优化| ISR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ISR --&gt;|去除fallback| DPR</span></span></code></pre></div><h2 id="综合对比" tabindex="-1">综合对比 <a class="header-anchor" href="#综合对比" aria-label="Permalink to &quot;综合对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>CSR</th><th>SSR</th><th>SSG</th><th>ISR</th><th>DPR</th></tr></thead><tbody><tr><td>首屏速度</td><td>慢</td><td>快</td><td>快</td><td>快</td><td>快（已缓存）/ 中（未缓存）</td></tr><tr><td>SEO</td><td>差</td><td>好</td><td>好</td><td>好</td><td>好</td></tr><tr><td>服务器成本</td><td>低（静态资源）</td><td>高（需实时计算）</td><td>低（CDN）</td><td>低（CDN + 按需构建）</td><td>中（CDN + Builder 按需渲染）</td></tr><tr><td>内容实时性</td><td>高（客户端请求）</td><td>高（每次实时渲染）</td><td>低（构建时确定）</td><td>中（缓存 + 异步更新）</td><td>高（缓存 + 实时渲染最新）</td></tr><tr><td>构建时间</td><td>快</td><td>慢（每次请求）</td><td>慢（全量构建）</td><td>快（按需构建）</td><td>快（按需构建，无需预构建）</td></tr><tr><td>部署方式</td><td>静态资源/CDN</td><td>Node 服务器</td><td>CDN</td><td>CDN + Builder</td><td>CDN + On-demand Builder</td></tr><tr><td>适用场景</td><td>后台、工具类</td><td>动态内容、SEO 要求高</td><td>内容固定、页面少</td><td>页面多、更新不频繁</td><td>海量页面、更新频繁</td></tr></tbody></table><h2 id="同构" tabindex="-1">同构 <a class="header-anchor" href="#同构" aria-label="Permalink to &quot;同构&quot;">​</a></h2><p>同构是指<strong>同一份代码</strong>既能在客户端运行也能在服务端运行，实现路由共享、组件共享、数据共享。</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[同一份代码] --&gt; B[服务端渲染HTML]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A --&gt; C[客户端hydration]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|首屏| D[用户看到完整页面]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt;|后续| E[客户端接管交互]</span></span></code></pre></div><p><strong>核心价值</strong>：结合 CSR + SSR 的优势——首屏用 SSR 提高速度和 SEO，后续交互用 CSR 保证体验。</p><blockquote><p><strong>同构 ≠ SSR</strong>：SSR 只描述&quot;渲染发生在服务端&quot;，不关心代码是否共享；同构强调&quot;同一套代码在服务端和客户端都能执行&quot;。传统 JSP/PHP 模板渲染也是 SSR，但不是同构。现代框架（Next.js、Nuxt.js）是同构 + SSR 的组合——同构是手段，SSR 是结果。</p></blockquote><h3 id="主流同构框架" tabindex="-1">主流同构框架 <a class="header-anchor" href="#主流同构框架" aria-label="Permalink to &quot;主流同构框架&quot;">​</a></h3><table tabindex="0"><thead><tr><th>框架</th><th>基于</th><th>特点</th></tr></thead><tbody><tr><td><strong>Next.js</strong></td><td>React</td><td>最成熟的 React SSR 框架，支持 SSR/SSG/ISR 混合，App Router</td></tr><tr><td><strong>Nuxt.js</strong></td><td>Vue</td><td>Vue 生态首选，支持 SSR/SSG，模块丰富</td></tr><tr><td><strong>Remix</strong></td><td>React</td><td>强调 Web 标准，嵌套路由，数据加载与路由绑定</td></tr><tr><td><strong>Astro</strong></td><td>框架无关</td><td>Islands 架构，默认零 JS，支持多框架混用</td></tr></tbody></table><h2 id="如何选择" tabindex="-1">如何选择 <a class="header-anchor" href="#如何选择" aria-label="Permalink to &quot;如何选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐方案</th></tr></thead><tbody><tr><td>后台管理系统、工具类应用</td><td>CSR</td></tr><tr><td>内容型网站、电商首页、需要 SEO</td><td>SSR</td></tr><tr><td>博客、文档站、官网</td><td>SSG</td></tr><tr><td>大型内容站、电商商品页</td><td>ISR</td></tr><tr><td>超大规模内容平台</td><td>DPR</td></tr></tbody></table><p>实际项目中通常<strong>混合使用</strong>：如首页 SSG + 动态页 SSR + 后台 CSR，根据页面特性选择最合适的渲染方式。</p><h3 id="混合渲染示例" tabindex="-1">混合渲染示例 <a class="header-anchor" href="#混合渲染示例" aria-label="Permalink to &quot;混合渲染示例&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>电商网站：</span></span>
<span class="line"><span>├── 首页/活动页 → SSG（内容固定，构建时生成，CDN 加速）</span></span>
<span class="line"><span>├── 商品详情页 → ISR（海量商品，按需构建，定期更新）</span></span>
<span class="line"><span>├── 搜索结果页 → SSR（实时数据，需要 SEO）</span></span>
<span class="line"><span>└── 购物车/订单页 → CSR（纯交互，无需 SEO）</span></span></code></pre></div>`,46)])])}const g=a(n,[["render",i]]);export{S as __pageData,g as default};
